package llm

import (
	"fmt"
	"os"
	"path/filepath"

	"strix-halo-vulkan/gguf"
)

// Config is the model's shape, read from the checkpoint's own metadata rather
// than transcribed from a config.json — which is the mistake L1 found in
// bench/modelshapes.go and had to correct four rows of.
type Config struct {
	Arch       string
	NLayer     int
	NEmbd      int
	NHead      int
	NHeadKV    int
	HC         int
	HCLowRank  int
	NExpert    int
	NExpertUsed int
	FFNExpert  int
	RMSEps     float32
	RopeBase   float32
	RopeDims   int
	VocabSize  int
}

// HC returns the hyper-connection block's shape.
func (c Config) HCConfig() HCConfig {
	return HCConfig{NEmbd: c.NEmbd, HC: c.HC, LowRank: c.HCLowRank, Eps: c.RMSEps}
}

// Model is a checkpoint held open: the GGUF mappings plus the metadata.
// Weights are dequantised on demand — at L2 the CPU reference touches a few
// tensors of a few layers, and dequantising 82 GB to reach them would be
// absurd.
type Model struct {
	Config Config
	files  []*gguf.File
	byName map[string]*gguf.File
}

// Open opens a checkpoint: a shard, or a directory holding the shards. Any
// shard works — the reader follows the split convention to the rest.
func Open(path string) (*Model, error) {
	shards, err := shardPaths(path)
	if err != nil {
		return nil, err
	}
	m := &Model{byName: map[string]*gguf.File{}}
	for _, p := range shards {
		f, err := gguf.Open(p)
		if err != nil {
			m.Close()
			return nil, err
		}
		m.files = append(m.files, f)
		for _, n := range f.TensorNames() {
			m.byName[n] = f
		}
	}
	if err := m.readConfig(); err != nil {
		m.Close()
		return nil, err
	}
	return m, nil
}

func shardPaths(path string) ([]string, error) {
	st, err := os.Stat(path)
	if err != nil {
		return nil, err
	}
	if !st.IsDir() {
		dir, base := filepath.Split(path)
		if i := indexSplit(base); i >= 0 {
			return filepath.Glob(filepath.Join(dir, base[:i]+"*.gguf"))
		}
		return []string{path}, nil
	}
	ps, err := filepath.Glob(filepath.Join(path, "*-of-*.gguf"))
	if err != nil || len(ps) > 0 {
		return ps, err
	}
	return filepath.Glob(filepath.Join(path, "*.gguf"))
}

// indexSplit finds the "-00001-of-00004" suffix a sharded GGUF carries.
func indexSplit(base string) int {
	for i := 0; i+16 <= len(base); i++ {
		if base[i] == '-' && base[i+6] == '-' && base[i+7:i+9] == "of" {
			return i
		}
	}
	return -1
}

func (m *Model) readConfig() error {
	arch, ok := m.str("general.architecture")
	if !ok {
		return fmt.Errorf("no general.architecture")
	}
	c := Config{Arch: arch}
	get := func(k string) uint64 { v, _ := m.uint(arch + "." + k); return v }
	c.NLayer = int(get("block_count"))
	c.NEmbd = int(get("embedding_length"))
	c.NHead = int(get("attention.head_count"))
	c.NHeadKV = int(get("attention.head_count_kv"))
	c.HC = int(get("hyper_connection.count"))
	c.HCLowRank = int(get("hyper_connection.low_rank"))
	c.NExpert = int(get("expert_count"))
	c.NExpertUsed = int(get("expert_used_count"))
	c.FFNExpert = int(get("expert_feed_forward_length"))
	c.RopeDims = int(get("rope.dimension_count"))
	if v, ok := m.float(arch + ".attention.layer_norm_rms_epsilon"); ok {
		c.RMSEps = float32(v)
	}
	if v, ok := m.float(arch + ".rope.freq_base"); ok {
		c.RopeBase = float32(v)
	}
	if t, err := m.Tensor("token_embd.weight"); err == nil {
		c.VocabSize = int(t.Dims[len(t.Dims)-1])
	}
	m.Config = c
	return nil
}

func (m *Model) str(k string) (string, bool) {
	for _, f := range m.files {
		if v, ok := f.Str(k); ok {
			return v, true
		}
	}
	return "", false
}

func (m *Model) uint(k string) (uint64, bool) {
	for _, f := range m.files {
		if v, ok := f.Uint(k); ok {
			return v, true
		}
	}
	return 0, false
}

func (m *Model) float(k string) (float64, bool) {
	for _, f := range m.files {
		if v, ok := f.Float(k); ok {
			return v, true
		}
	}
	return 0, false
}

// Tensor looks a tensor up across the shards.
func (m *Model) Tensor(name string) (*gguf.Tensor, error) {
	f, ok := m.byName[name]
	if !ok {
		return nil, fmt.Errorf("no tensor %q", name)
	}
	return f.Get(name)
}

// F32 dequantises a whole tensor. The result is in ggml's memory order, so a
// weight stated [in, out] reads back as out rows of in values — the row-major
// [out][in] a dot product wants.
func (m *Model) F32(name string) ([]float32, error) {
	t, err := m.Tensor(name)
	if err != nil {
		return nil, err
	}
	return t.Dequantize(nil)
}

// Embedding gathers one row of token_embd, which is a lookup and not a
// matmul: 675 MB of Q8_0 that only ever has n_tokens rows read out of it.
func (m *Model) Embedding(id int32) ([]float32, error) {
	t, err := m.Tensor("token_embd.weight")
	if err != nil {
		return nil, err
	}
	return t.DequantizeRow(int64(id), nil)
}

// HCWeights loads one mixer. side is "attn" or "ffn"; layer <0 selects the
// head mixer, which has no inject because there is no block after it.
func (m *Model) HCWeights(layer int, side string) (HCWeights, error) {
	var w HCWeights
	var prefix string
	if layer < 0 {
		prefix = "output_hc_"
	} else {
		prefix = fmt.Sprintf("blk.%d.hc_%s_", layer, side)
	}
	var err error
	if w.Norm, err = m.F32(prefix + "norm.weight"); err != nil {
		return w, err
	}
	if w.Down, err = m.F32(prefix + "down.weight"); err != nil {
		return w, err
	}
	if w.Up, err = m.F32(prefix + "up.weight"); err != nil {
		return w, err
	}
	if layer >= 0 {
		if w.Inject, err = m.F32(prefix + "inject.weight"); err != nil {
			return w, err
		}
	}
	return w, nil
}

// Close unmaps the shards.
func (m *Model) Close() error {
	var first error
	for _, f := range m.files {
		if err := f.Close(); err != nil && first == nil {
			first = err
		}
	}
	m.files = nil
	return first
}
