package llm

import (
	"math"
	"testing"
)

// q8 quantises a vector the way ggml_quantize_row_q8_1 does: blocks of 32,
// symmetric, d = amax/127, and returns d*round(x/d) — the values the integer
// dot product actually sees.
func q8(x []float32, block int) []float32 {
	out := make([]float32, len(x))
	for b := 0; b < len(x); b += block {
		e := b + block
		if e > len(x) {
			e = len(x)
		}
		var amax float32
		for _, v := range x[b:e] {
			if a := float32(math.Abs(float64(v))); a > amax {
				amax = a
			}
		}
		if amax == 0 {
			continue
		}
		d := amax / 127
		for i := b; i < e; i++ {
			out[i] = d * float32(math.Round(float64(x[i]/d)))
		}
	}
	return out
}

